def eat_full(hit_rate, tlb_time, mem_time, fault_rate, fault_time):
    normal = tlb_time + mem_time + (1 - hit_rate) * mem_time
    return (1 - fault_rate) * normal + fault_rate * fault_time

def fault_rate_needed(target_eat, hit_rate, tlb_time, mem_time, fault_time):
    normal = tlb_time + mem_time + (1 - hit_rate) * mem_time
    if target_eat <= normal:
        return 0.0
    if target_eat >= fault_time:
        return 1.0
    return (target_eat - normal) / (fault_time - normal)

print(eat_full(0.9, 20, 100, 0.001, 10000000))
print(fault_rate_needed(150, 0.9, 20, 100, 10130))
